-- User-editable 2D prototype maps; not marketed as complete MOBA/MMORPG/sports gameplay.
create table if not exists public.game_scene_templates(
 code text primary key check(code ~ '^[a-z0-9-]{3,80}$'),
 name text not null,
 genre text not null,
 description text not null,
 scene jsonb not null check(jsonb_typeof(scene)='object'),
 is_active boolean not null default true,
 created_at timestamptz not null default now()
);
alter table public.game_scene_templates enable row level security;
revoke all on public.game_scene_templates from anon,authenticated;
grant select on public.game_scene_templates to anon,authenticated;
drop policy if exists game_scene_templates_public_read on public.game_scene_templates;
create policy game_scene_templates_public_read on public.game_scene_templates for select to anon,authenticated using(is_active);
insert into public.game_scene_templates(code,name,genre,description,scene) values
('arena-strategy','Bản đồ đấu trường chiến thuật','Đấu trường','Khung cảnh để phát triển gameplay MOBA, đội, kỹ năng và trụ. Hiện chỉ có di chuyển và mục tiêu 2D.','{"title":"Đấu trường chiến thuật","background":"#172554","player":{"x":7,"y":45,"emoji":"⚔️","speed":1.5},"objects":[{"id":"energy-1","kind":"coin","x":18,"y":19,"w":7,"h":10,"label":"💠"},{"id":"energy-2","kind":"coin","x":42,"y":49,"w":7,"h":10,"label":"💠"},{"id":"energy-3","kind":"coin","x":68,"y":18,"w":7,"h":10,"label":"💠"},{"id":"energy-4","kind":"coin","x":80,"y":66,"w":7,"h":10,"label":"💠"},{"id":"tower-1","kind":"wall","x":30,"y":34,"w":8,"h":26,"label":"🏰"},{"id":"tower-2","kind":"wall","x":61,"y":39,"w":9,"h":24,"label":"🛡️"},{"id":"base","kind":"goal","x":89,"y":45,"w":9,"h":14,"label":"🚩"}]}'::jsonb),
