('football-training','Sân tập bóng đá 2D','Thể thao','Bố cục sân bóng và mục tiêu; chưa có vật lý bóng, AI hậu vệ hay trận đấu online.','{"title":"Thử thách sân cỏ","background":"#0b6638","player":{"x":8,"y":45,"emoji":"🏃","speed":1.8},"objects":[{"id":"ball-1","kind":"coin","x":24,"y":48,"w":7,"h":10,"label":"⚽"},{"id":"ball-2","kind":"coin","x":49,"y":22,"w":7,"h":10,"label":"⚽"},{"id":"ball-3","kind":"coin","x":70,"y":71,"w":7,"h":10,"label":"⚽"},{"id":"defender-1","kind":"wall","x":39,"y":34,"w":9,"h":28,"label":"🛡️"},{"id":"defender-2","kind":"wall","x":68,"y":27,"w":9,"h":23,"label":"🛡️"},{"id":"goal","kind":"goal","x":88,"y":43,"w":11,"h":16,"label":"🥅"}]}'::jsonb),
